using System; using System.Data; using System.Data.SqlClient; using System.Text; using System.Web;
namespace schoolms { public partial class TeacherSchedule : System.Web.UI.Page {
protected void Page_Load(object sender,EventArgs e){string email=Session["teacher"] as string;if(email==null){Response.Redirect("Teacher_login.aspx");return;}if(!IsPostBack)LoadSchedule(email);}
void LoadSchedule(string email){try{using(SqlConnection con=Db.CreateConnection()){con.Open();string teacherName=email;using(SqlCommand c=new SqlCommand("SELECT Name FROM Teacher WHERE Email=@Email",con)){c.Parameters.Add("@Email",SqlDbType.NVarChar,150).Value=email;object n=c.ExecuteScalar();if(n!=null&&n!=DBNull.Value)teacherName=Convert.ToString(n);}litTeacher.Text=HttpUtility.HtmlEncode(teacherName)+" &middot; "+HttpUtility.HtmlEncode(email);DataTable periods=new DataTable();using(SqlDataAdapter da=new SqlDataAdapter("SELECT SortOrder,TimeSlot,PeriodLabel,IsBreak FROM SchedulePeriods ORDER BY SortOrder",con))da.Fill(periods);DataTable rows=new DataTable();using(SqlDataAdapter da=new SqlDataAdapter("SELECT DayNo,SortOrder,Subject,Room,Grade FROM TeacherSchedule WHERE TeacherEmail=@Email",con)){da.SelectCommand.Parameters.Add("@Email",SqlDbType.NVarChar,150).Value=email;da.Fill(rows);}var map=new System.Collections.Generic.Dictionary<string,string>();foreach(DataRow r in rows.Rows){string key=Convert.ToInt32(r["DayNo"])+":"+Convert.ToInt32(r["SortOrder"]);string room=r["Room"]==DBNull.Value?"":Convert.ToString(r["Room"]);string grade=r["Grade"]==DBNull.Value?"":Convert.ToString(r["Grade"]);map[key]=HttpUtility.HtmlEncode(Convert.ToString(r["Subject"]))+"<br/><small>"+HttpUtility.HtmlEncode(room)+" &middot; "+HttpUtility.HtmlEncode(grade)+"</small>";}StringBuilder b=new StringBuilder("<table><thead><tr><th>Time</th><th>Monday</th><th>Tuesday</th><th>Wednesday</th><th>Thursday</th><th>Friday</th></tr></thead><tbody>");foreach(DataRow p in periods.Rows){int order=Convert.ToInt32(p["SortOrder"]);bool br=Convert.ToBoolean(p["IsBreak"]);b.Append("<tr><th>").Append(HttpUtility.HtmlEncode(Convert.ToString(p["TimeSlot"]))).Append("</th>");for(int day=1;day<=5;day++){if(br)b.Append("<td class='break'>").Append(HttpUtility.HtmlEncode(Convert.ToString(p["PeriodLabel"]))).Append("</td>");else{string v;if(map.TryGetValue(day+":"+order,out v))b.Append("<td class='subject'>").Append(v).Append("</td>");else b.Append("<td class='free'>Free</td>");}}b.Append("</tr>");}b.Append("</tbody></table>");litSchedule.Text=b.ToString();}}catch(SqlException){litSchedule.Text="<div class='msg'>Unable to load the teacher schedule. Please check the database connection.</div>";}}
}}
